        return False
    return 2 * seconds <= max(2, n) * g

def get_rest_seconds(position, green_seconds):
    remaining_seconds = max(2, n) - position
    if remaining_seconds % green_seconds == 0:
        return remaining_seconds // green_seconds
    else:
        return remaining_seconds // green_seconds + 1

def get_min_crossing_time(positions, g, r):
    max_change = max(positions) - min(positions)

    time = 0
    remaining = max_change

    while remaining > 0:
        if is_safe_time(time + remaining):
            time += remaining
            remaining = 0
        else:
            next_position = min(positions) + remaining
            remaining -= get_rest_seconds(next_position, g)

    if remaining > 1:
        return -1
    else:
        return time + (n - min(positions) if n > max(positions) else n)

