import sys

def simulate(n, k, ts):
    t = sum(ts)
    if t <= 2 * n * (n + 1) // 2:
        return t
    else:
        return f'Not possible with {t} tokens, expected number of hours is {t / 3 * (n + 1) * (n + 1)}'

def minimum_expected_hours(n, k, ts):
    t = sum(ts)

    if t <= 2 * n * (n + 1) // 2:
        return (2 * n * (n + 1) // 2) / (n + 1)

    parts = t // (n + 1)
    if (t - parts * (n + 1)) % (n - 1) == 0:
        units = (t - parts * (n + 1)) // (n - 1)
    else:
        units = (t - parts * (n + 1)) // (n - 1) + 1

    moderate_p = k
    for i in range(k - 1):
        moderate_p -= max(0, t // (n + 2) - units)
        if moderate_p <= 0:
            return "Not possible"

    matches = units * k
    for i in range(k - 1):
        matches += min(moderate_p, max(0, t // (n + 2) - units))
        moderate_p -= min(moderate_p, max(0, t // (n + 2) - units))

    hours = (2 * n * (n + 1) // 2 - 2 * matches) + max(0, t // (n + 2) - matches)
    if hours * (n + 1) != 2 * n * (n + 1) // 2:
        return f'Not possible with {hours * (n + 1)} hours, expected number of hours is {2 * n * (n + 1) // 2 - hours}'

    return f'{hours * (n + 1)}'

