from bisect import bisect_right
from math import sqrt

def find_min_expected_hours(n, k, tokens, left, right):
    defect = 0
    for i in range(k):
        l, r = bisect_right(tokens, left), bisect_right(tokens, right)
        lack = max(l - i - 1, 0)
        excess = min(i + 2, r - i - 2)
        bag_size = left * tokens[i]
        full_bag = max(0, (lack + excess) // 2 - bag_size)
        if i != k - 1:
            full_bag += max(0, tokens[i + 1] - left) // 2
        if int(tokens[i]) > sqrt(defect):
            defect += int(tokens[i])
        defect += token_defect(tokens[i], full_bag)

    return defect - n


def token_defect(tok_dev, full_bag):
    try:
        x = round((full_bag + tok_dev) / (8 - tok_dev))
        return (full_bag + x * (8 - tok_dev)) / (8 - tok_dev)
    except:
        return full_bag + tok_dev
