    for neighbor in graph[current]:
        if not visited[neighbor]:
            visited[neighbor] = 1
            match[neighbor] = current
            for next_neighbor in graph[neighbor]:
                if match[next_neighbor] == -1:
                    dfs(graph, match[next_neighbor], visited, match)
            break
    else:
