def solve(n, d):
    graph = defaultdict(list)

    # Build the graph
    for _ in range(n - 1):
        u, v = map(int, input().split())
        graph[u].append(v)

    # Find the maximum matching for N planets
    n_max_matching = 0
    for i in range(1, n + 1):
        if dfs(graph, i, [0] * (n + 1), [-1] * (n + 1)):
            n_max_matching += 1

    # Subtract the matching if all planets can reach the first planet without a match
    for i in range(1, n + 1):
        if dfs(graph, i, [0] * (n + 1), [-1] * (n + 1)) and n - n_max_matching <= n:
            n_max_matching += 1

    return pow(2, n_max_matching, MOD)

