    return True

def can_place(i, blocks):
    non_decreasing = True
    non_increasing = True
    for j in range(i):
        if blocks[i] == blocks[j] != blocks[j - 1]:
            return False
        if blocks[i] == blocks[j]:
            non_decreasing &= blocks[i] == blocks[j]
        if blocks[i] == blocks[j] + 1:
            non_increasing &= blocks[i] < blocks[j] + 2
    return non_decreasing and non_increasing

def count_ways(n, k, blocks):
    count = 1  # Starting from 1 to exclude 0-indexed zero blocks
    for i in range(1, 2 * n + 1):
        if can_place(i, blocks):
            count += 1
    return count

