import sys
from typing import List
from collections import defaultdict

class TreeNode:
    def __init__(self, val=0, children=None):
        self.val = val
        self.children = children if children is not None else []

def dfs(root: TreeNode) -> List[int]:
    def dfs_helper(node: TreeNode):
        sequence = [node.val]
        for child in node.children:
            children = dfs_helper(child)
            sequence.extend(children)
        return sequence
    return dfs_helper(root)

def query_tree(query: str, args: List[int]) -> int:
    if query == '1':
        u, v = args
        k = dfs(vs[root][u - 1])[v - 1]
        return k
    elif query == '2':
        v, h = args
        ancestor = vs[root][-h]
        sequence = dfs(ancestor)
        inner = sequence[:h + 1]
        return inner.index(v)
    elif query == '3':
        dist = args[0]
        sequence = dfs(vs[root][-1])
        return sequence[::-1].index(dist)

